<?php declare(strict_types=1);use FastWebsite\Core\View;?>
<section class="admin-page-heading"><div><p class="eyebrow">MVP · Engagement</p><h1>Partnerships and impact</h1><p>Published records remain editable, and workflow controls are available here.</p></div><div class="heading-actions"><?php if($canCreate):?><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/engagement/impact/create">Add impact story</a><?php endif;?><?php if($canCreate&&$canManagePartnerships):?><a class="button button-primary" href="<?=View::escape($baseUrl)?>admin/engagement/partnerships/create">Add partnership</a><?php endif;?></div></section><section class="admin-panel"><h2>Partnerships</h2><?php if($partnerships===[]):?><p class="admin-empty">No formal partnerships recorded.</p><?php else:?><div class="table-scroll"><table class="admin-table"><thead><tr><th>Partnership</th><th>Partner</th><th>Type</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($partnerships as$p):?><tr><th><?=View::escape($p['title'])?></th><td><?=View::escape($p['partner_name'])?></td><td><?=View::escape(ucwords(str_replace('_',' ',$p['partnership_type'])))?></td><td><?=View::escape($p['status'])?></td><td><div class="table-actions"><?php if($canEdit&&$canManagePartnerships):?><a href="<?=View::escape($baseUrl)?>admin/engagement/partnerships/<?=(int)$p['id']?>/edit">Edit</a><?php $a=$p['status']==='published'?'archive':($p['status']==='archived'?'restore':'publish');if($a!=='publish'||$canPublish):?><form method="post" action="<?=View::escape($baseUrl)?>admin/engagement/partnerships/<?=(int)$p['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="link-button" name="action" value="<?=$a?>"><?=ucfirst($a)?></button></form><?php endif;endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="admin-panel" id="impact"><h2>Impact stories</h2><?php if($impacts===[]):?><p class="admin-empty">No impact stories recorded.</p><?php else:?><div class="table-scroll"><table class="admin-table"><thead><tr><th>Story</th><th>Date</th><th>Department</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($impacts as$i):?><tr><th><?=View::escape($i['title'])?></th><td><?=View::escape($i['impact_date']??'Not set')?></td><td><?=View::escape($i['department_name']??'Faculty-wide')?></td><td><?=View::escape($i['status'])?></td><td><div class="table-actions"><?php if($canEdit):?><a href="<?=View::escape($baseUrl)?>admin/engagement/impact/<?=(int)$i['id']?>/edit">Edit</a><?php $a=$i['status']==='published'?'archive':($i['status']==='archived'?'restore':'publish');if($a!=='publish'||$canPublish):?><form method="post" action="<?=View::escape($baseUrl)?>admin/engagement/impact/<?=(int)$i['id']?>/workflow"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><button class="link-button" name="action" value="<?=$a?>"><?=ucfirst($a)?></button></form><?php endif;endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
